   SET pay50_occ_date         = #{req.occDate}
     , pay50_desc             = #{req.desc}
     , pay50_corp_id          = #{req.corpId}
     , pay50_tax_type         = #{req.taxType}
     , pay50_amt              = #{req.amt}
     , pay50_tax              = #{req.tax}
     , pay50_settle_amt       = #{req.settleAmt}
     , pay50_due_date         = #{req.dueDate}
     , pay50_pay_method_cd    = #{req.payMethodCode}
     , pay50_pay_account_info = #{req.payAccountInfo}
     , pay50_account_cd       = #{req.accountCode}
     , pay50_note             = #{req.note}
     , pay50_deposit_id       = #{req.depositId}
     , pay50_ast_id           = #{req.astId}
 WHERE pay50_expense_id = #{expenseId}
   AND pay50_company_id = #{companyId}

