INSERT INTO pay50_expense
     ( pay50_expense_id, pay50_company_id, pay50_expense_cd, pay50_occ_date, pay50_desc, pay50_corp_id, pay50_tax_type
     , pay50_amt, pay50_tax, pay50_settle_amt, pay50_due_date, pay50_pay_method_cd, pay50_pay_account_info, pay50_account_cd
     , pay50_appr_emp_id, pay50_expense_appr_id, pay50_deposit_id, pay50_settle_emp_id, pay50_settle_date
     , pay50_benefit_id, pay50_transport_std_ym, pay50_biz_card_std_ym, pay50_biz_card_corp_cd )
VALUES ( #{expenseId}, #{companyId}, #{row.expenseCode}, #{row.occDate}, #{row.desc}, #{row.corpId}, #{row.taxType}
       , #{row.amt}, #{row.tax}, #{row.settleAmt}, #{row.dueDate}, #{row.payMethodCode}, #{row.payAccountInfo}, #{row.accountCode}
       , #{row.apprEmpId}, #{row.expenseApprId}, #{row.depositId}, #{settleEmpId}, #{row.settleDate}
       , #{row.benefitId}, #{row.transportStdYm}, #{row.bizCardStdYm}, #{row.bizCardCorpCode} )

